UPDATE CMM_LIST_PREFIX
SET	BRD_ID       = #{brdId},
	PREFIX_NAME  = #{prefixName},
	PREFIX_ORDER = #{prefixOrder}
WHERE PREFIX_ID    =#{prefixId}

UPDATE CMM_LIST_PREFIX
SET    USE_YN     = 'N'
WHERE  PREFIX_ID    =#{prefixId}

